#include <vector>
#include <cmath>
#include <algorithm>
#include <omp.h>

struct COOElement {
    size_t row, column;
    double value;
};

void solveLinearSystem(std::vector<COOElement> const& A,
                       std::vector<double> const& b,
                       std::vector<double> &x,
                       size_t N) {
    // Build a dense matrix from COO (parallel-safe accumulation with atomics)
    std::vector<double> M(N * N, 0.0);

    #pragma omp parallel for schedule(static)
    for (long long k = 0; k < static_cast<long long>(A.size()); ++k) {
        const size_t r = A[static_cast<size_t>(k)].row;
        const size_t c = A[static_cast<size_t>(k)].column;
        const double v = A[static_cast<size_t>(k)].value;
        if (r < N && c < N) {
            #pragma omp atomic update
            M[r * N + c] += v;
        }
    }

    // RHS copy
    std::vector<double> rhs(N, 0.0);
    #pragma omp parallel for schedule(static)
    for (long long i = 0; i < static_cast<long long>(N); ++i) {
        rhs[static_cast<size_t>(i)] = (static_cast<size_t>(i) < b.size()) ? b[static_cast<size_t>(i)] : 0.0;
    }

    // Prepare output
    x.assign(N, 0.0);

    // Gaussian elimination with partial pivoting
    for (size_t i = 0; i < N; ++i) {
        // Pivot search (sequential for correctness and simplicity)
        size_t pivot = i;
        double maxAbs = std::fabs(M[i * N + i]);
        for (size_t r = i + 1; r < N; ++r) {
            const double v = std::fabs(M[r * N + i]);
            if (v > maxAbs) {
                maxAbs = v;
                pivot = r;
            }
        }

        // Singular or nearly singular: leave x as-is (best effort)
        if (maxAbs <= 1e-15) {
            continue;
        }

        // Swap rows if needed (parallelized across columns)
        if (pivot != i) {
            #pragma omp parallel for schedule(static)
            for (long long c = 0; c < static_cast<long long>(N); ++c) {
                std::swap(M[i * N + static_cast<size_t>(c)], M[pivot * N + static_cast<size_t>(c)]);
            }
            std::swap(rhs[i], rhs[pivot]);
        }

        const double diag = M[i * N + i];

        // Eliminate rows below pivot in parallel; each thread owns one row r
        #pragma omp parallel for schedule(static)
        for (long long rr = static_cast<long long>(i) + 1; rr < static_cast<long long>(N); ++rr) {
            const size_t r = static_cast<size_t>(rr);
            const double factor = M[r * N + i] / diag;
            M[r * N + i] = 0.0;
            for (size_t c = i + 1; c < N; ++c) {
                M[r * N + c] -= factor * M[i * N + c];
            }
            rhs[r] -= factor * rhs[i];
        }
    }

    // Back substitution (sequential due to dependency chain)
    for (long long ii = static_cast<long long>(N) - 1; ii >= 0; --ii) {
        const size_t i = static_cast<size_t>(ii);
        double sum = rhs[i];

        double dot = 0.0;
        #pragma omp parallel for reduction(+:dot) schedule(static)
        for (long long c = static_cast<long long>(i) + 1; c < static_cast<long long>(N); ++c) {
            dot += M[i * N + static_cast<size_t>(c)] * x[static_cast<size_t>(c)];
        }
        sum -= dot;

        const double diag = M[i * N + i];
        if (std::fabs(diag) > 1e-15) {
            x[i] = sum / diag;
        } else {
            x[i] = 0.0; // best effort for singular rows
        }
    }
}
